package com.shadow.mobile;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.provider.Settings;
import android.view.*;
import android.view.inputmethod.EditorInfo;
import android.widget.*;
import android.speech.tts.TextToSpeech;
import java.util.*;

/** MOD-37.11: SHADOW unified Jarvis-style UI shell. */
public final class JarvisMainActivity extends Activity implements TextToSpeech.OnInitListener {
    private static final int MIC=801;
    private final int BG=Color.rgb(13,14,17),SURFACE=Color.rgb(29,31,36),TEXT=Color.rgb(241,243,246),MUTED=Color.rgb(155,160,170);
    private ShadowCore core; private ShadowCloudClient cloud; private ShadowVoiceRecognizer voice; private ShadowRemoteController remotes; private LinearLayout messages; private EditText input; private ShadowStatusView status; private TextToSpeech tts; private boolean conversation=true,cloudOnline;
    private int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);} private GradientDrawable bg(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}
    private TextView tv(String s,float z){TextView v=new TextView(this);v.setText(s);v.setTextColor(TEXT);v.setTextSize(z);return v;}
    private void stage(String s){status.setText(ShadowProcessIndicators.render(s));}
    @Override public void onCreate(Bundle b){super.onCreate(b);core=new ShadowCore(this);cloud=new ShadowCloudClient(this);remotes=new ShadowRemoteController(this);voice=new ShadowVoiceRecognizer(this,new ShadowVoiceRecognizer.Listener(){public void onListening(){stage("listening");}public void onText(String t){input.setText(t);send();}public void onError(String m){system(m);if(conversation)again();}});tts=new TextToSpeech(this,this);ui();check();}
    private void ui(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);TextView menu=tv("☰",24);menu.setGravity(Gravity.CENTER);head.addView(menu,new LinearLayout.LayoutParams(dp(48),dp(52)));ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.shadow_logo);head.addView(logo,new LinearLayout.LayoutParams(dp(50),dp(52)));LinearLayout tb=new LinearLayout(this);tb.setOrientation(LinearLayout.VERTICAL);tb.setGravity(Gravity.CENTER);TextView title=tv("SHADOW",18);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);tb.addView(title);status=new ShadowStatusView(this);status.setTextColor(Color.rgb(112,210,160));status.setTextSize(11);status.setGravity(Gravity.CENTER);status.setText(ShadowProcessIndicators.render("thinking"));tb.addView(status);head.addView(tb,new LinearLayout.LayoutParams(0,dp(52),1));TextView more=tv("⋮",26);more.setGravity(Gravity.CENTER);head.addView(more,new LinearLayout.LayoutParams(dp(48),dp(52)));root.addView(head);
        ScrollView sc=new ScrollView(this);messages=new LinearLayout(this);messages.setOrientation(LinearLayout.VERTICAL);messages.setPadding(dp(12),dp(10),dp(12),dp(18));sc.addView(messages);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));assistant("أهلاً محمد 👋\nأنا SHADOW — Z.\nالعقل + الأدوات + الصوت + الذاكرة منظومة واحدة.\nأونلاين: AI / Web / Images. أوفلاين: Core / Device.");
        LinearLayout wrap=new LinearLayout(this);wrap.setPadding(dp(4),dp(4),dp(4),dp(4));wrap.setBackground(bg(SURFACE,24));TextView plus=tv("＋",25);plus.setGravity(Gravity.CENTER);wrap.addView(plus,new LinearLayout.LayoutParams(dp(48),dp(56)));input=new EditText(this);input.setHint("Message SHADOW");input.setHintTextColor(MUTED);input.setTextColor(TEXT);input.setTextSize(16);input.setBackgroundColor(Color.TRANSPARENT);wrap.addView(input,new LinearLayout.LayoutParams(0,dp(56),1));TextView mic=tv("🎙",24);mic.setGravity(Gravity.CENTER);wrap.addView(mic,new LinearLayout.LayoutParams(dp(52),dp(56)));TextView send=tv("➤",23);send.setGravity(Gravity.CENTER);wrap.addView(send,new LinearLayout.LayoutParams(dp(52),dp(56)));root.addView(wrap,new LinearLayout.LayoutParams(-1,dp(64)));setContentView(root);menu.setOnClickListener(v->attach());more.setOnClickListener(v->features());plus.setOnClickListener(v->attach());mic.setOnClickListener(v->listen());send.setOnClickListener(v->send());input.setOnEditorActionListener((v,a,e)->{if(a==EditorInfo.IME_ACTION_SEND){send();return true;}return false;});}
    private void user(String s){TextView v=tv(s,16);v.setPadding(dp(14),dp(9),dp(14),dp(9));v.setBackground(bg(Color.rgb(42,44,51),18));messages.addView(v);bottom();}private void assistant(String s){TextView v=tv(s,16);v.setPadding(0,dp(8),dp(18),dp(8));v.setAutoLinkMask(android.text.util.Linkify.WEB_URLS);messages.addView(v);bottom();}private void system(String s){TextView v=tv(s,11);v.setTextColor(MUTED);messages.addView(v);bottom();}private void bottom(){messages.post(()->{ViewParent p=messages.getParent();if(p instanceof ScrollView)((ScrollView)p).fullScroll(View.FOCUS_DOWN);});}
    private void check(){new Thread(()->{cloudOnline=cloud.health();runOnUiThread(()->stage(cloudOnline?"done":"thinking"));}).start();}
    private void send(){String s=input.getText().toString().trim();if(s.isEmpty())return;user(s);input.setText("");stage("thinking");String local=ShadowPhoneController.execute(this,s);if(local!=null){stage("executing");assistant(local);speak(local);stage("done");again();return;}if(s.toLowerCase(Locale.ROOT).contains("صمم صورة")||s.toLowerCase(Locale.ROOT).contains("generate image")){stage("designing");system("SHADOW • image design request received.");}stage("searching");new Thread(()->{try{ShadowCloudClient.CloudReply r=cloud.chat(s);cloudOnline=true;runOnUiThread(()->{stage("analyzing");assistant(r.answer);stage("speaking");speak(r.answer);stage("done");again();});}catch(Throwable e){cloudOnline=false;String a=core.handle(s);if(a==null||a.trim().isEmpty())a=core.offlineChat(s);String answer=a;runOnUiThread(()->{assistant(answer);stage("speaking");speak(answer);stage("done");again();});}}).start();}
    private void listen(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},MIC);return;}stage("listening");voice.start("ar-EG");}private void again(){if(conversation)new android.os.Handler().postDelayed(()->listen(),2200);}
    private void attach(){PopupMenu p=new PopupMenu(this,findViewById(android.R.id.content));p.getMenu().add("Files");p.getMenu().add("Photos");p.getMenu().add("Camera");p.setOnMenuItemClickListener(i->{system("Attached: "+i.getTitle());return true;});p.show();}
    private void features(){PopupMenu p=new PopupMenu(this,findViewById(android.R.id.content));String[] a={"📺 TV Remote","❄️ AC Remote","🔎 Remote capabilities","🌐 Web search","🎨 Image design","📱 Deep phone control","🧠 Development Agent","Profile / Memory","System status","Settings"};for(String s:a)p.getMenu().add(s);p.setOnMenuItemClickListener(i->{String n=i.getTitle().toString();if(n.startsWith("📺")||n.startsWith("❄️")||n.startsWith("🔎"))remotes.showCenter();else if(n.startsWith("📱"))startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));else if(n.startsWith("🌐")){input.setText("ابحث أونلاين عن ");input.requestFocus();}else if(n.startsWith("🎨")){input.setText("صمم صورة: ");input.requestFocus();}else if(n.startsWith("🧠")){system("Development Agent: analyze → plan → approve → edit → test → report");}else if(n.equals("System status"))assistant(core.handle("status"));else if(n.equals("Settings"))startActivity(new Intent(Settings.ACTION_SETTINGS));return true;});p.show();}
    private void speak(String s){if(tts==null)return;try{tts.setLanguage(new Locale("ar","EG"));tts.setPitch(.72f);tts.setSpeechRate(.96f);tts.speak(s,TextToSpeech.QUEUE_FLUSH,null,"shadow");}catch(Exception ignored){}}
    @Override public void onInit(int c){if(tts!=null){tts.setLanguage(new Locale("ar","EG"));tts.setPitch(.72f);}}
    @Override protected void onDestroy(){voice.stop();if(tts!=null){tts.stop();tts.shutdown();}super.onDestroy();}
}
